atus='SUCCEEDED'"],"assertion_contract":{"mode":"EXPLICIT_PASS_WHEN_SUBSET","pass_when":{"router_positive_status":"READY_INSPECTION","unauthorized_profile_status":"BLOCKED","inventory_sources_readback":true,"consumer_bindings_readback":true,"unproven_e2e_reported_as_gap":true,"exact_evidence_doc_readback":true}},"action_steps":["READ_DECLARED_SOURCES_ONCE","VERIFY_POSITIVE_AND_NEGATIVE_ROUTER_READBACK","COMPARE_CONSUMER_BINDINGS_AND_STATES","REQUIRE_CURRENT_SOURCE_DOC_READBACK","RECORD_C1_ASSERTION_ONLY_ON_EVIDENCE","PERSIST_WITH_EXISTING_CHECKPOINT_TRANSITION","USE_RETURNED_BOOTSTRAP"],"forbidden":["INFER_E2E_FROM_CANDIDATE_WORKER","INFER_GOLDEN_FROM_HISTORICAL_SUCCEEDED","MUTATE_DOMAIN_DATA","CHANGE_C2_OR_C3","SYNTHETIC_PASS_WITHOUT_VERIFIED_READBACK"],"evidence_ref":"github://cristhianlujan/claude-persona-lf-patch/docs/programming-agent/ANALYSIS_A16Q_C1_ROUTER_CONSUMER_INVENTORY_V1.md"}$a16spec$::jsonb;
