BEGIN
  SELECT work_item_id,unit_metadata INTO STRICT v_work,v_metadata
  FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code='A16Q' AND id=807 AND work_item_id=1126
  FOR UPDATE;
  IF v_work<>1126 OR v_metadata->>'schema'<>'PROGRAMMING_A16Q_ARCHITECTURE_RESEARCH_V1'
     OR v_metadata ? 'source_pack_v2' OR v_metadata ? 'action_specs_v1'
     OR EXISTS (SELECT 1 FROM programacion.engineering_work_checkpoints
                WHERE work_item_id=1126 AND status<>'PENDING')
     OR (SELECT count(*) FROM programacion.engineering_work_checkpoints
         WHERE work_item_id=1126)<>3
  THEN RAISE EXCEPTION 'A16Q_C1_PRESTATE_DRIFT'; END IF;

  v_next := v_metadata || jsonb_build_object(
    'source_pack_v2',jsonb_build_object('checkpoint_inputs',jsonb_build_object('A16Q_C1',v_source)),
    'action_specs_v1',jsonb_build_object('A16Q_C1',v_spec),
    'a16q_c1_inventory_v1',v_observed
  );

  UPDATE programacion.engineering_plan_units
     SET unit_metadata=v_next
   WHERE plan_code=v_plan AND unit_code='A16Q' AND id=807 AND work_item_id=1126;

  IF (SELECT count(*) FROM programacion.engineering_plan_units
      WHERE id=807
        AND unit_metadata#>>'{action_specs_v1,A16Q_C1,action_kind}'='READBACK_ONCE'
        AND unit_metadata#>>'{a16q_c1_inventory_v1,state}'='RESEARCH_EVIDENCE_ONLY_NOT_CHECKPOINT_PASS'
        AND jsonb_array_length(unit_metadata#>'{source_pack_v2,checkpoint_inputs,A16Q_C1,inputs,queries}')=8
        AND unit_metadata#>'{action_specs_v1,A16Q_C2}' IS NULL
        AND unit_metadata#>'{action_specs_v1,A16Q_C3}' IS NULL
     ) <> 1 OR
     (SELECT count(*) FROM programacion.engineering_work_checkpoints
      WHERE work_item_id=1126 AND status='PENDING') <> 3
  THEN RAISE EXCEPTION 'A16Q_C1_POSTWRITE_READBACK_FAILED'; END IF;
END;
$a16q_c1$;
